O=Path(__file__).parent;ref=json.loads((O/'curved-added-fit.json').read_text());a=[r for r in ref['validation'] if r['group']=='development'];b=json.loads((O/'curved-added-oracle-diagnostic.json').read_text())['results'];fig,axes=plt.subplots(1,2,figsize=(11,4));x=np.arange(6)
for ax,key,label in [(axes[0],'bank_rmse_deg','Bank RMSE (deg)'),(axes[1],'heading_final_error_deg','Absolute final heading error (deg)')]:
 ax.bar(x-.18,[abs(r[key]) for r in a],.36,label='Past-data initialization');ax.bar(x+.18,[abs(r[key]) for r in b],.36,label='Initial state fitted to future');ax.set_xticks(x,['HR447','HR450','HR508','TL326','TL402','TL3387'],rotation=25);ax.set_ylabel(label);ax.grid(axis='y',alpha=.2)
